window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6e59a9a955659bf8"]={"versions": [{"id": "FIG-6e59a9a955659bf8", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der AUTOSAR-XML-Persistenzregeln (Model Persistence Rules for XML). Das Diagramm definiert den Kontrollfluss zur XML-Repräsentation von Modell-Properties, bei denen keine Aggregation vorliegt (<code>aggregation = none</code>), also für Assoziationen bzw. Referenzen auf andere Modellelemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>:Property</strong>: Eingangsobjekt bzw. Ausgangszustand der Aktivität, repräsentiert ein zu serialisierendes Property-Element ohne Aggregation.\n</li><li><strong>Entscheidungsknoten (Decision Node) / Merge-Knoten</strong>: Verzweigung und anschließende Zusammenführung basierend auf der Bedingung <code>propertyWrapper?</code>.\n</li><li><strong>Aktionen</strong>:\n<ul class=\"fig-list\"><li><code>[APRXML0017] Create reference property (1)</code>: Aktion zur Erzeugung einer Referenz-Property mit Wrapper-Element.\n</li><li><code>[APRXML0018] Create reference property (0)</code>: Aktion zur Erzeugung einer Referenz-Property ohne Wrapper-Element.\n</li></ul>\n</li><li><strong>ActivityFinal</strong>: Endknoten der Aktivität nach der Zusammenführung beider Zweige.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausgehend von <code>:Property</code> wird am ersten Entscheidungsknoten geprüft, ob ein Property-Wrapper erforderlich ist (<code>propertyWrapper?</code>).\n</li><li>Wenn die Guard-Bedingung <code>[propertyWrapperElement]</code> wahr ist, verzweigt der Ablauf auf die Aktion <code>[APRXML0017] Create reference property (1)</code>.\n</li><li>Wenn die Guard-Bedingung <code>[NOT propertyWrapperElement]</code> wahr ist, verzweigt der Ablauf auf die alternative Aktion <code>[APRXML0018] Create reference property (0)</code>.\n</li><li>Beide Pfade münden über den nachfolgenden Merge-Knoten gemeinsam in den Knoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm operationalisiert die normativen XML-Serialisierungsregeln APRXML0017 und APRXML0018 für Referenzeigenschaften (<code>aggregation = none</code>). Modellierungs- und Generierungswerkzeuge für AUTOSAR-XML müssen anhand des Vorhandenseins oder Nichtvorhandenseins des Wrapper-Elements entscheiden, ob eine Referenz mit umschließendem XML-Tag <code>(1)</code> oder direkt ohne umschließenden Wrapper <code>(0)</code> serialisiert wird.</p>"}, {"id": "FIG-4974d68fa949a942", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der AUTOSAR-XML-Persistenzregeln (Model Persistence Rules for XML). Das Diagramm definiert den Kontrollfluss zur XML-Repräsentation von Modell-Properties, bei denen keine Aggregation vorliegt (<code>aggregation = none</code>), also für Assoziationen bzw. Referenzen auf andere Modellelemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>:Property</strong>: Eingangsobjekt bzw. Ausgangszustand der Aktivität, repräsentiert ein zu serialisierendes Property-Element ohne Aggregation.\n</li><li><strong>Entscheidungsknoten (Decision Node) / Merge-Knoten</strong>: Verzweigung und anschließende Zusammenführung basierend auf der Bedingung <code>propertyWrapper?</code>.\n</li><li><strong>Aktionen</strong>:\n<ul class=\"fig-list\"><li><code>[APRXML0017] Create reference property (1)</code>: Aktion zur Erzeugung einer Referenz-Property mit Wrapper-Element.\n</li><li><code>[APRXML0018] Create reference property (0)</code>: Aktion zur Erzeugung einer Referenz-Property ohne Wrapper-Element.\n</li></ul>\n</li><li><strong>ActivityFinal</strong>: Endknoten der Aktivität nach der Zusammenführung beider Zweige.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausgehend von <code>:Property</code> wird am ersten Entscheidungsknoten geprüft, ob ein Property-Wrapper erforderlich ist (<code>propertyWrapper?</code>).\n</li><li>Wenn die Guard-Bedingung <code>[propertyWrapperElement]</code> wahr ist, verzweigt der Ablauf auf die Aktion <code>[APRXML0017] Create reference property (1)</code>.\n</li><li>Wenn die Guard-Bedingung <code>[NOT propertyWrapperElement]</code> wahr ist, verzweigt der Ablauf auf die alternative Aktion <code>[APRXML0018] Create reference property (0)</code>.\n</li><li>Beide Pfade münden über den nachfolgenden Merge-Knoten gemeinsam in den Knoten <code>ActivityFinal</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm operationalisiert die normativen XML-Serialisierungsregeln APRXML0017 und APRXML0018 für Referenzeigenschaften (<code>aggregation = none</code>). Modellierungs- und Generierungswerkzeuge für AUTOSAR-XML müssen anhand des Vorhandenseins oder Nichtvorhandenseins des Wrapper-Elements entscheiden, ob eine Referenz mit umschließendem XML-Tag <code>(1)</code> oder direkt ohne umschließenden Wrapper <code>(0)</code> serialisiert wird.</p>"}], "trans": [{"from": "FIG-6e59a9a955659bf8", "to": "FIG-4974d68fa949a942", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
